import json,platform,shutil,sys
info={'system':platform.system(),'node':platform.node(),'release':platform.release(),'machine':platform.machine(),'python':platform.python_version()}
print(json.dumps(info))
import resource
for k,v in (('RLIMIT_AS',resource.RLIMIT_AS),('RLIMIT_CPU',resource.RLIMIT_CPU)):
    print(k,json.dumps(resource.getrlimit(v)))
print('rlimit_as_readable')
for p in ['/','/tmp']:
    d=shutil.disk_usage(p); print(p,json.dumps({'total':d.total,'used':d.used,'free':d.free}))

